const catalog = [{sku:"CHAIR-101",name:"Кресло базовое",price_rub:6500,stock:15},{sku:"CHAIR-205",name:"Кресло эргономичное",price_rub:12500,stock:8},{sku:"DESK-110",name:"Стол письменный",price_rub:14000,stock:5}];
const sku = String(typeof query === "string" ? query : query?.sku ?? "").trim().toUpperCase();
const result = catalog.find(r=>r.sku===sku);
return JSON.stringify(result ? {status:"found",...result,source:"учебный каталог"} : {status:"not_found",sku,message:"В учебном каталоге товар отсутствует"});
